package convertplan

import (
	"regexp"
	"strings"
)

var (
	nxPluginImport = regexp.MustCompile(`(?m)^import\s+nx\s+from\s+['"]@nx/eslint-plugin['"];?[ \t]*\r?\n`)
	nxConfigSpread = regexp.MustCompile(`\.\.\.nx\.configs\[['"]flat/(\w+)['"]\],?`)
)

// RewriteNxESLint rewrites an ESLint flat config generated by Nx so it no
// longer needs Nx: @nx/eslint-plugin's base, TypeScript and JavaScript
// presets become @eslint/js and typescript-eslint (what they wrap), and the
// Nx-only rules (module boundaries and dependency checks, which read the Nx
// project graph) are removed. ok is false when anything Nx-specific remains.
func RewriteNxESLint(text string) (string, bool) {
	out := text
	if nxPluginImport.MatchString(out) {
		out = nxPluginImport.ReplaceAllString(out, "import js from '@eslint/js';\nimport tseslint from 'typescript-eslint';\n")
		ok := true
		out = nxConfigSpread.ReplaceAllStringFunc(out, func(m string) string {
			switch nxConfigSpread.FindStringSubmatch(m)[1] {
			case "base":
				return "js.configs.recommended,"
			case "typescript":
				return "...tseslint.configs.recommended,"
			case "javascript":
				return ""
			}
			ok = false
			return m
		})
		if !ok {
			return text, false
		}
	}
	for _, rule := range []string{"@nx/enforce-module-boundaries", "@nx/dependency-checks"} {
		for {
			i := strings.Index(out, "'"+rule+"'")
			if i < 0 {
				i = strings.Index(out, `"`+rule+`"`)
			}
			if i < 0 {
				break
			}
			next, removed := removeRule(out, i, rule)
			if !removed {
				return text, false
			}
			out = next
		}
	}
	out = blankLines.ReplaceAllString(out, "\n")
	// Nx named in a comment is not a dependency on it.
	if code := stripLineComments(out); strings.Contains(code, "@nx/") || strings.Contains(code, "nx.") {
		return text, false
	}
	return out, true
}

var blankLines = regexp.MustCompile(`\n[ \t]*\n([ \t]*\n)+`)

// removeRule deletes a rule. A rule that is the only one in a block whose
// rules exist for it (a dependency check on JSON files) takes the block
// with it; otherwise only the rule entry goes.
func removeRule(src string, at int, rule string) (string, bool) {
	if strings.Contains(rule, "dependency-checks") {
		if start, end, ok := enclosingElement(src, at); ok {
			end = skipComma(src, end)
			return trimLine(src, withLeadingComments(src, start), end), true
		}
	}
	colon := strings.Index(src[at:], ":")
	if colon < 0 {
		return src, false
	}
	value := skipSpace(src, at+colon+1)
	end, ok := matching(src, value)
	if !ok {
		return src, false
	}
	end = skipComma(src, end+1)
	return trimLine(src, at, end), true
}

// enclosingElement finds the object literal around at that is an element of
// an array (preceded by "[" or ","), returning its start and the index after
// its closing brace.
func enclosingElement(src string, at int) (int, int, bool) {
	best := -1
	bestEnd := -1
	for i := at - 1; i >= 0; i-- {
		if src[i] != '{' {
			continue
		}
		end, ok := matching(src, i)
		if !ok || end < at {
			continue
		}
		prev := strings.TrimRight(src[:i], " \t\r\n")
		if strings.HasSuffix(prev, ",") || strings.HasSuffix(prev, "[") {
			best, bestEnd = i, end+1
			break
		}
	}
	return best, bestEnd, best >= 0
}

// matching returns the index of the bracket closing the one at open,
// skipping string literals and comments.
func matching(src string, open int) (int, bool) {
	pairs := map[byte]byte{'{': '}', '[': ']', '(': ')'}
	if _, ok := pairs[src[open]]; !ok {
		return 0, false
	}
	var stack []byte
	for i := open; i < len(src); i++ {
		switch c := src[i]; c {
		case '\'', '"', '`':
			for i++; i < len(src) && src[i] != c; i++ {
				if src[i] == '\\' {
					i++
				}
			}
		case '/':
			if i+1 < len(src) && src[i+1] == '/' {
				for i < len(src) && src[i] != '\n' {
					i++
				}
			}
		case '{', '[', '(':
			stack = append(stack, pairs[c])
		case '}', ']', ')':
			if len(stack) == 0 || stack[len(stack)-1] != c {
				return 0, false
			}
			stack = stack[:len(stack)-1]
			if len(stack) == 0 {
				return i, true
			}
		}
	}
	return 0, false
}

func skipSpace(src string, i int) int {
	for i < len(src) && strings.ContainsRune(" \t\r\n", rune(src[i])) {
		i++
	}
	return i
}

func skipComma(src string, i int) int {
	j := skipSpace(src, i)
	if j < len(src) && src[j] == ',' {
		return j + 1
	}
	return i
}

// trimLine removes src[start:end] and the indentation before it.
func trimLine(src string, start, end int) string {
	for start > 0 && (src[start-1] == ' ' || src[start-1] == '\t') {
		start--
	}
	if start > 0 && src[start-1] == '\n' {
		if end < len(src) && src[end] == '\n' {
			end++
		} else if end+1 < len(src) && src[end] == '\r' && src[end+1] == '\n' {
			end += 2
		}
	}
	return src[:start] + src[end:]
}

// withLeadingComments moves start back over the line comments directly above
// the element that begins there: they explain it, and go with it. A start that
// is not the first thing on its line is left alone.
func withLeadingComments(src string, start int) int {
	lineStart := strings.LastIndex(src[:start], "\n") + 1
	if strings.TrimSpace(src[lineStart:start]) != "" {
		return start
	}
	for lineStart > 0 {
		prevStart := strings.LastIndex(src[:lineStart-1], "\n") + 1
		if !strings.HasPrefix(strings.TrimSpace(src[prevStart:lineStart-1]), "//") {
			break
		}
		lineStart = prevStart
	}
	return lineStart
}
